\begin{enumerate}
\item[(1)] The identity function $\delta_I$, where $\delta_I(I)=I$ for every $I\in~Id(R)$, is an expansion function of ideals of $R$.\\
\item[(2)] For each ideal $I,$ define $\delta_{\sqrt{I}}(I)=\sqrt{I}$.  Then $\delta_{\sqrt{I}}$ is an expansion function of ideals of $R$.
\end{enumerate}

\begin{enumerate}
\item[(1)] Let $R$ be a commutative ring, $\delta_I$ be an expansion function of $Id(R)$ and $m$ and $n$ positive be integers, then a proper ideal $I$ of $R$ is a weakly $(m,n)-$closed $\delta_I-$primary ideal of $R$ if and only if $I$ is a weakly $(m,n)-$closed ideal of $R$.\\
\item[(2)] It is clear that any $(m,n)-$closed $\delta-$primary ideal of $R$ is weakly $(m,n)-$closed $\delta-$primary ideal.  The converse need not hold.\\
\item[(3)] A weakly $(m,n)-$closed $\delta-$primary ideal does not be weakly $(\acute{m},n)-$closed $\delta-$primary for $\acute{m}<m$.
\end{enumerate}

Let $R$ be a commutative ring, $\delta$ and $\gamma$ be expansion functions of $Id(R)$ with $\delta(I)\subseteq\gamma(I)$, $m$ and $n$ be integers with $1\leq~n<m$, and $I$ be a proper ideal of $R$.
\begin{enumerate}
\item[(1)] If $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$, then $I$ is a weakly $(m,n)-$closed $\gamma-$primary ideal of $R$.
\item[(2)] If $\delta(I)$ is a weakly $(m,n)-$closed ideal of $R$, then $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$.
\end{enumerate}

\begin{enumerate}
\item[(1)] Since $\delta(I)\subseteq\gamma(I)$ and $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$, then the claim follows.
\item[(2)]  Let $0\neq~a^m\in~I\subseteq\delta(I)$ for some $a\in~R$.  Since $\delta(I)$ is a weakly $(m,n)-$closed ideal of $R$, then $a^n\in\delta(I)$.  Therefore, $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$.
\end{enumerate}

\label{3}
Let $R$ and $A$ be commutative rings, $m$ and $n$ be positive integers, and $f:R\longrightarrow~A$ be a $\delta\gamma-$homomorphism, where $\delta$ is an expansion function of $Id(R)$ and $\gamma$ is an expansion function of $Id(A)$.\\
\begin{enumerate}
\item[(1)] If $f$ is injective and $J$ is a weakly $(m,n)-$closed $\gamma-$primary ideal of $A$, then $f^{-1}(J)$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$.\\
\item[(2)] If $f$ is surjective and $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$ containing $Ker(f)$, then $f(I)$ is a weakly $(m,n)-$closed $\gamma-$primary ideal of $A$.
\end{enumerate}

\label{80}
Let $R$ be a commutative ring, $\delta$ be an expansion function of $Id(R)$, $m$ and $n$ be positive integers, and $I\subseteq~J$ be prober ideals of $R$.
\begin{enumerate}
\item[(1)] If $J$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$, then $J/I$ is a weakly $(m,n)-$closed $\delta_q-$primary ideal of $R/I$.
\item[(2)] If $I$ is an $(m,n)-$closed $\delta-$primary ideal of $R$ and $J/I$ is a weakly $(m,n)-$closed $\delta_q-$primary ideal of $R/I$, then $J$ is an $(m,n)-$closed $\delta-$primary ideal of $R$.
\item[(3)] If $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$ and $J/I$ is a weakly $(m,n)-$closed $\delta_q-$primary ideal of $R/I$, then $J$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$.
\end{enumerate}

\begin{enumerate}
\item[(1)] Follows directly from Theorem \ref{3} $(2)$.\\
\item[(2)] Let $a^m\in~J$ for $a\in~R$.  If $a^m\in~I$, then $a^n\in\delta(I)\subseteq\delta(J)$.  Assume that $a^m\not\in~I$.  Then, we have $I\neq(a+I)^m\in~J/I$.  Since $J/I$ is a weakly $(m,n)-$closed $\delta_q-$primary ideal of $R/I$.  Then, $(a+I)^n=a^n+I\in\delta_q(J/I)$.  Thus, $a^n\in\delta(J)$.  Therefore, $J$ is an $(m,n)-$closed $\delta-$primary ideal of $R$.\\
\item[(3)] Let $0\neq~a^m\in~J$ for $a\in~R$.  Then by a similar argument as in part (2), one can show that $J$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$.
\end{enumerate}

Let $R$ be a commutative ring, $I$ be a proper ideal of $R$, $m$ and $n$ be positive integers, $P\subseteq~R\backslash\{0\}$ be a multiplicative set with $I\cap~P=\phi$, and $\delta_P$ be an expansion function of $Id(R_P)$ such that $\delta_P(I_P)=(\delta(I))_P$ where $\delta$ is an expansion function of $Id(R)$.  Then the following statements are equivalent.
\begin{enumerate}
\item[(1)] $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$.\\
\item[(2)] $I_P$ is a weakly $(m,n)-$closed $\delta_P-$primary ideal of $R_P$ for every prime (or maximal) ideal $P$ of $R$.
\end{enumerate}

\label{4}
Let $R=R_1\times~R_2$, where $R_1$ and $R_2$ are commutative rings, $\delta_i$ be an expansion function of $Id(R_i)$ for each $i\in\{1,2\}$, $I_1$ be a proper ideal of $R_1$, $I_2$ be a proper ideal of $R_2$, and $m$ and $n$ be positive integers with $1\leq~n<m$.  Then the following statements are equivalent.
\begin{enumerate}
\item[(1)] $I_1\times~R_2$ is a weakly $(m,n)-$closed $\delta_\times-$primary ideal of $R$.\\
\item[(2)] $I_1$ is an $(m,n)-$closed $\delta_1-$primary ideal of $R_1$.\\
\item[(3)] $I_1\times~R_2$ is an $(m,n)-$closed $\delta_\times-$primary ideal of $R$.
\end{enumerate}

\label{34}
Let $R$ be a commutative ring, $\delta$ be an expansion function of $Id(R)$, $m$ and $n$ be integers with $1\leq~n<~m$, $I$ be a prober ideal of $R$, and $M$ be an $R-$module.  Then the following statements are equivalent.\\
\begin{enumerate}
\item[(1)] $I(+)M$ is a weakly $(m,n)-$closed $\delta_{(+)}-$primary ideal of $R(+)M$ that is not $(m,n)-$closed $\delta_{(+)}-$primary.\\
\item[(2)] $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $R$ that is not $(m,n)-$closed $\delta-$primary and $m(x^{m-1}M)=0$ for every $(m,n)-$unbrekable-zero element $x$ of $I$.
\end{enumerate}

\label{30}
Let $f:A\rightarrow~B$ be a homomorphism of rings and $J$ be an ideal of $B.$  Let $I$ be a proper ideal of $A.$  Then the following statements are equivalent.
\begin{enumerate}
\item[(1)] $I$ is an $(m,n)-$closed $\delta-$primary ideal of $A.$
\item[(2)] $I\bowtie^{f}J$ is an $(m,n)-$closed $\delta_{\bowtie^{f}}-$primary ideal of $A\bowtie^{f}J.$
\end{enumerate}

\label{31}
Let $f:A\rightarrow B$ be a homomorphism of rings and $J$ be an ideal of $B.$  Then the following statements are equivalent.
\begin{enumerate}
\item[(1)] $I\bowtie^{f}J$ is a weakly $(m,n)-$closed $\delta_{\bowtie^{f}}-$primary ideal of $A\bowtie^{f}J$ that is not $(m,n)-$closed $\delta_{\bowtie^{f}}-$primary.
\item[(2)] $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $A$ that is not $(m,n)-$closed $\delta-$primary and for every $\delta$-$(m,n)$-unbreakable-zero element $a$ of $I$ we have $(f(a)+j)^{m}=0$ for every $j\in~J$.
\end{enumerate}

Let $f:A\rightarrow~B$ be a homomorphism of rings and $J$ be an ideal of $B.$  If $char(f(A)+J)=m$ and $J^{m}=0.$  Then the following statements are equivalent.
\begin{enumerate}
\item[(1)] $I\bowtie^{f}J$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $A\bowtie^{f}J$ that is not $(m,n)-$closed $\delta-$primary.
\item[(2)] $I$ is a weakly $(m,n)-$closed $\delta$-primary ideal of $A$ that is not $(m,n)-$closed $\delta$-primary.
\end{enumerate}

For every $j\in J,$ we have $$(f(a)+j)^{m}=f(a^{m})=\displaystyle\sum_{k=1}^{m-1}\left(
\begin{array}{cccc}
m\\
k\\
\end{array}
\right)f(a^{m-k}j^{k}+j^{m}.$$
As $J^{m}=0$ we gate $j^{m}=0$ for every $j\in J$ on the other hand we have $\left(
\begin{array}{cccc}
m\\
k\\
\end{array}
\right)=0$ since $ch(f(A)+j)=m$ and $m$ divides $\left(
\begin{array}{cccc}
m\\
k\\
\end{array}
\right).$

Let $A$ be a commutative ring, and $I$ be a proper ideal of $A.$ Let $K$ be a proper ideal of $A.$ Then the following statements are equivalent.
\begin{enumerate}
\item[(1)] $K\bowtie~I$ is a weakly $(m,n)-$closed $\delta_{\bowtie}-$primary ideal of $A\bowtie~I$ which is not $(m,n)-$closed $\delta_{\bowtie}-$primary.
\item[(2)] $K$ is weakly $(m,n)-$closed $\delta-$primary ideal of $A$ which is not $(m,n)-$closed $\delta-$primary and $(a+i)^{m}=0$ for every an $(m,n)$-unbreakable element $a$ of $K$ and every element $i\in~I$.
\end{enumerate}

\label{32}
Let $A$ be a commutative ring, $M$ be an $A$-module.  Let $I$ be a proper ideal of $A.$  Then the following statements are equivalent.
\begin{enumerate}
\item[(1)] $I(+)M$ is a weakly $(m,n)-$closed $\delta_{(+)}-$primary ideal of $A(+)M$ that is not $(m,n)-$closed $\delta_{(+)}-$primary.
\item[(2)] $I$ is a weakly $(m,n)-$closed $\delta-$primary ideal of $A$ that is not $(m,n)-$closed $\delta-$primary and $m(a^{m-1})M=0$ for every $(m,n)$-unbreakable element $a$ of $I.$
\end{enumerate}

The following statements are equivalent.
\begin{enumerate}
\item[(1)] $\overline{K}^{f}$ is a weakly $(m,n)-$closed $\delta_{\bowtie^{f}}-$primary ideal of $A\bowtie^{f}J$ which is not $(m,n)-$closed $\delta_{\bowtie^{f}}-$primary.
\item[(2)] $K$ is a weakly $(m,n)-$closed $\delta_{1}-$primary ideal of $f(A)+J$ which is not $(m,n)-$closed $\delta_{1}-$primary and for every $(m,n)$-unbreakable-zero $f(a)+j$ of $K$ we have $a^{m}=0.$
\end{enumerate}
